"""Generate isolated support tokens for independently hosted project pages."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def render_support_tokens(source: str) -> str:
    start = source.index("html:root {") + len("html:root {")
    end = source.index("\n}", start)
    return (
        "/* Generated by scripts/generate_support_tokens.py from css/tokens.css.\n"
        "   Keep standalone host palettes unchanged; do not edit this file directly. */\n"
        ".support-dialog, .support-floating-trigger {" + source[start:end] + "\n}\n"
    )


if __name__ == "__main__":
    (ROOT / "css/support-tokens.css").write_text(render_support_tokens((ROOT / "css/tokens.css").read_text()))
    print("Generated isolated support tokens from the canonical light palette and metrics.")
